/**
 * list-findings.mjs
 *
 * Print the catalogue as a table, grouped by kind. Generated rather than
 * hand-maintained, so that `docs/05-failure-modes.md` cannot drift from
 * `tools/catalogue.mjs`, and CI checks the generated file against this output.
 */

import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';
import { FINDINGS } from './catalogue.mjs';

const TITLES = {
  rejected: 'Rejected: the code refuses these and says why',
  prevented: 'Prevented: the code avoids these, and a pair proves it',
  residual: 'Residual: what the fixes do not clear, asserted on the fixed side of a pair',
};

export function render() {
  const lines = [
    '# Failure modes',
    '',
    'Generated by `npm run catalogue` from `tools/catalogue.mjs`. CI compares this',
    'file against that output, so an edit here is reverted by the next check and an',
    'edit there has to be reflected here.',
    '',
  ];

  for (const kind of ['rejected', 'prevented', 'residual']) {
    const group = FINDINGS.filter((f) => f.kind === kind);
    lines.push(`## ${TITLES[kind]}`, '');
    lines.push(`${group.length} of them.`, '');
    lines.push('| id | module | pair | what it is |', '|---|---|---|---|');
    for (const finding of group) {
      lines.push(`| \`${finding.id}\` | ${finding.module} | ${finding.pair ?? ''} | ${finding.summary} |`);
    }
    lines.push('');
  }

  return `${lines.join('\n').trimEnd()}\n`;
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))) {
  process.stdout.write(render());
}
